/* 红旗渠爱国浏览器：仅定制 Firefox 原生新标签页/主页。 */
@-moz-document url("about:newtab"),url("about:home"){
 :root{color-scheme:light!important;--newtab-background-color:#faf7f0!important;--newtab-text-primary-color:#4c2c1d!important;--newtab-text-secondary-color:#795c49!important;--newtab-primary-action-background:#a50d17!important;--button-background-color-primary:#a50d17!important}
 body{background:#faf7f0 url("data:image/webp;base64,") center bottom/cover fixed no-repeat!important;margin:0!important;min-width:0!important;overflow-x:hidden!important}
 .outer-wrapper,.nova-outer-wrapper,.container,.body-wrapper{display:block!important;width:100%!important;max-width:none!important;min-width:0!important;padding:0!important;margin:0!important;background:transparent!important}
 #root,.nova-outer-wrapper{min-height:0!important}.sidebar-inline-start,.sidebar-inline-end{display:none!important}
 main.content-main,.outer-wrapper>main{display:grid!important;grid-template-columns:minmax(0,1fr)!important;place-items:center!important;min-height:calc(100svh - 60px)!important;height:auto!important;width:100%!important;padding:32px 24px 198px!important;margin:0!important;transform:none!important}
