 .logo-and-wordmark{display:block!important;width:470px!important;max-width:90%!important;height:auto!important;aspect-ratio:1.5!important;margin:0 auto!important;padding:0!important;background:url("data:image/png;base64,") center/contain no-repeat!important}
 .logo-and-wordmark .logo,.logo-and-wordmark .wordmark{display:none!important}
 .logo-and-wordmark-wrapper::after{content:"自力更生 · 艰苦创业 · 团结协作 · 无私奉献";display:block;font:20px/1.7 "SimSun","Songti SC",serif;letter-spacing:.16em;color:#4c2c1d;margin-top:16px}
 .search-wrapper{display:block!important;grid-template-columns:none!important;position:relative!important;inset:auto!important;width:100%!important;max-width:none!important;min-width:0!important;padding:0!important;margin:0!important;background:transparent!important;box-shadow:none!important;transform:none!important}
 .search-inner-wrapper{display:block!important;width:100%!important;max-width:none!important;min-width:0!important;height:70px!important;margin:0!important;padding:0!important}
