 .search-handoff-button:hover{box-shadow:0 7px 22px #5d30111c!important}
 .fake-textbox{font:16px/1.6 "Microsoft YaHei UI",sans-serif!important;color:#765e50!important;height:auto!important;min-height:26px!important;opacity:1!important;visibility:visible!important}
 .top-sites{display:block!important;position:relative!important;width:100%!important;min-width:0!important;padding:0!important;margin:24px 0 0!important}
 .top-sites-list-wrapper{width:100%!important;margin:0!important;padding:0!important}
 .top-sites-list{display:flex!important;flex-wrap:wrap!important;justify-content:center!important;align-items:center!important;gap:4px!important;width:100%!important;padding:0!important;margin:0!important}
 .top-site-outer{width:154px!important;height:52px!important;min-width:0!important;margin:0!important;padding:0!important;border-radius:10px!important}
 .top-site-inner{width:100%!important;height:52px!important}.top-site-button{display:flex!important;flex-direction:row!important;justify-content:center!important;align-items:center!important;gap:11px!important;height:52px!important;min-height:52px!important;padding:9px 12px!important;box-sizing:border-box!important}
 .tile,.top-site-icon,.icon-stack,.icon-wrapper{width:33px!important;height:33px!important;min-width:33px!important;min-height:0!important;background-size:contain!important;border-radius:0!important}
 .tile{background:transparent!important;box-shadow:none!important;margin:0!important;align-self:center!important;flex:0 0 33px!important}
 .title{width:auto!important;min-width:0!important;max-width:84px!important;height:auto!important;margin:0!important;padding:0!important;color:#4c2c1d!important;text-align:left!important;font:14px/1.6 "Microsoft YaHei UI",sans-serif!important}
 .top-site-outer .title span{white-space:nowrap!important}.top-site-outer .title-label{display:block!important;width:100%!important;height:23px!important;min-height:0!important;line-height:23px!important;overflow:hidden!important;text-overflow:ellipsis!important}.top-site-button:not([data-is-sponsored-link="true"]) .sponsored-label{display:none!important}.context-menu-button{inset-inline-end:0!important}
 .add-button-tile{display:flex!important;align-items:center!important;justify-content:center!important;width:40px!important;min-width:40px!important;height:52px!important}.add-button{position:static!important;inset:auto!important;transform:none!important;margin:0!important}
 .add-button,.open-customization-button{--button-background-color-primary:#a50d17!important;--button-background-color-primary-hover:#850b12!important;--button-background-color-primary-active:#850b12!important}
 body::after{content:"为人民服务";display:block;position:fixed;bottom:0;left:0;right:0;height:60px;padding:12px 24px 22px;box-sizing:border-box;text-align:center;font:14px/26px "SimSun",serif;letter-spacing:.4em;color:#732d1d;pointer-events:none}
 @media(max-width:720px){main.content-main,.outer-wrapper>main{padding:28px 22px 100px!important}.logo-and-wordmark{width:350px!important}.logo-and-wordmark-wrapper::after{font-size:16px;letter-spacing:.08em;text-wrap:balance;margin-top:14px}.top-sites-list{gap:0!important}.top-site-outer{width:136px!important}.title{font-size:12px!important}.tile,.top-site-icon,.icon-stack,.icon-wrapper{width:25px!important;height:25px!important;min-width:25px!important}.tile{flex-basis:25px!important}.search-inner-wrapper,content-search-handoff-ui,.search-handoff-button{height:62px!important;min-height:62px!important}}
 @media(max-width:440px){.logo-and-wordmark{max-width:96%!important}.logo-and-wordmark-wrapper::after{font-size:14px}main.content-main,.outer-wrapper>main{padding-inline:16px!important}}
 @media(max-height:780px) and (min-width:721px){main.content-main,.outer-wrapper>main{padding-block:24px 100px!important}.logo-and-wordmark{width:340px!important}.logo-and-wordmark-wrapper::after{font-size:17px;margin-top:10px}.logo-and-wordmark-wrapper{margin-bottom:16px!important}.top-sites{margin-top:15px!important}}
 .top-site-button[href="https://www.gov.cn/"] .tile{background-image:url("data:image/png;base64,")!important;background-size:contain!important;background-position:center!important;background-repeat:no-repeat!important}
.top-site-button[href="https://www.12371.cn/"] .tile{background-image:url("data:image/png;base64,")!important;background-size:contain!important;background-position:center!important;background-repeat:no-repeat!important}
.top-site-button[href="https://www.people.com.cn/"] .tile{background-image:url("data:image/png;base64,")!important;background-size:contain!important;background-position:center!important;background-repeat:no-repeat!important}
.top-site-button[href="https://www.news.cn/"] .tile{background-image:url("data:image/png;base64,")!important;background-size:contain!important;background-position:center!important;background-repeat:no-repeat!important}
.top-site-button[href="https://www.people.com.cn/"] .tile{background-size:auto 33px!important;background-position:left center!important}
@media(max-width:720px){.top-site-button[href="https://www.people.com.cn/"] .tile{background-size:auto 25px!important}}
.top-site-button[href="https://www.gov.cn/"] .tile>*,.top-site-button[href="https://www.12371.cn/"] .tile>*,.top-site-button[href="https://www.people.com.cn/"] .tile>*,.top-site-button[href="https://www.news.cn/"] .tile>*{visibility:hidden!important}
}
